using System;\nusing RestSharp;\nusing Newtonsoft.Json;\nusing Serilog;\n\nnamespace AutomationFramework.API.BusinessLogic\n{\n    public class PetApiHelper\n    {\n        private readonly RestClient _client;\n\n        public PetApiHelper()\n        {\n            _client = new RestClient(\"https://petstore.swagger.io/v2/pet\");\n        }\n\n        public IRestResponse SendGetRequest(int id)\n        {\n            var request = new RestRequest($\"{id}\", Method.GET);\n            return ExecuteRequest(request);\n        }\n\n        public IRestResponse SendPostRequest(Pet pet)\n        {\n            var request = new RestRequest(Method.POST);\n            request.AddJsonBody(pet);\n            return ExecuteRequest(request);\n        }\n\n        public IRestResponse SendPutRequest(Pet pet)\n        {\n            var request = new RestRequest(Method.PUT);\n            request.AddJsonBody(pet);\n            return ExecuteRequest(request);\n        }\n\n        public IRestResponse SendDeleteRequest(int id)\n        {\n            var request = new RestRequest($\"{id}\", Method.DELETE);\n            return ExecuteRequest(request);\n        }\n\n        private IRestResponse ExecuteRequest(RestRequest request)\n        {\n            try\n            {\n                var response = _client.Execute(request);\n                Log.Information($\"Request to {request.Resource} completed with status {response.StatusCode}.\");\n                return response;\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error executing request.\");\n                throw;\n            }\n        }\n    }\n\n    public class Pet\n    {\n        public int Id { get; set; }\n        public string Name { get; set; }\n        public string Status { get; set; }\n    }\n}